  display: flex;
  align-items: center;
  &.allow {
    background: #c9dfd3;
  }

  border-radius: 16px;
  padding: 32px;

  .cardContainer {
    width: 100%;

    img,
    i {
      align-self: flex-start;
      margin-right: 16px;
    }

    .selfie,
    .selfiePlaceholder {
      width: 72px;
      height: 72px;
      border-radius: 50%;
      object-fit: cover;
      border: 2px solid #118c4f; // green3 color approx
