342:
.exam-header-battery-container {
  position: absolute;
  right: 16px;
  top: 6px;
  height: 12px;
  line-height: 12px;

  font-family: Roboto;
  font-size: 10px;
  font-weight: bold;

  display: flex;
  flex-direction: row;
  align-content: center;
  align-items: center;

  & > div {
    height: 12px;
  }

  & > div.label {
    padding-right: 4px;
  }

  & > div.icon > img {
    padding-bottom: 2px;
  }

  &.low-battery {
    color: #ab2334;
  }

  &.break-mode {
    top: 24px;
    right: 32px;
    background-color: #505050;
    height: 32px;
    width: 80px;
    border-radius: 5px;
    opacity: 0.97;
    justify-content: center;
    border: solid 2px #1e1e1e;

    & > div.label {
      padding-right: 2px;
      font-size: 12px;
      color: #ffffff;
    }

    & > div.icon {
      width: 25px;
      height: 12px;
      padding-left: 5px;
    }

    & > div.icon > img {
      width: 20px;
      height: 12px;
    }

    &.low-battery,
    &.low-battery > div.label {
      background-color: #ffffff;
      color: #ab2334;
    }
  }

  @media (forced-colors: active) {
    .icon {
      forced-color-adjust: none !important;
      background-color: #ffffff !important;
    }
  }
}

387:
