@import "../utility/variables";

.jump-button-wrapper {
  box-sizing: content-box;
  padding: 16px;
  position: relative;

  .jump-button {
    align-items: center;
    background-color: $fontColorAlt2;
    border: 0;
    box-sizing: border-box;
    color: white;
    display: flex;
    font-family: Roboto;
    font-size: 24px;
    font-weight: bold;
    height: 40px;
    justify-content: center;
    letter-spacing: normal;
    padding: 0;
    width: 40px;

    &:hover {
      background-color: #255e9b;
    }

    &.unanswered,
    &.booklet {
      background-color: transparent;
      border-color: black;
      border-width: 1px;
      color: $fontColorAlt2;

      &:hover {
        background-color: #f0f0f0;
      }
    }

    &.unanswered {
      border-style: dashed;
    }

    &.booklet {
      border-style: solid;
    }

    &:focus,
    &:focus-within {
      outline: none;
      text-decoration: underline;
    }
  }

  .flag {
    background-image: url("data:image/svg+xml;base64,");
    background-size: unset;
    height: 16px;
    left: 48px;
    position: absolute;
    top: 8px;
    visibility: hidden;
    width: 16px;

    &.flagged {
      visibility: visible;
    }
  }

  .pin {
    background-image: url("data:image/svg+xml,%3Csvg width='16' height='17' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M1.5 6.75C1.5 2.964 4.37 0 8.033 0 11.659 0 14.5 2.964 14.5 6.75c0 3.614-2.32 5.818-5.859 8.768L8 16.051l-.641-.533C3.82 12.568 1.5 10.364 1.5 6.75z' fill='%23fff'/%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M8 13.443c-3.164-2.689-4.5-4.31-4.5-6.693C3.5 4.087 5.491 2 8.033 2 10.538 2 12.5 4.087 12.5 6.75c0 2.383-1.336 4.004-4.5 6.693M8.033 0C4.37 0 1.5 2.964 1.5 6.75c0 3.614 2.32 5.818 5.859 8.768l.641.533.641-.533c3.539-2.95 5.859-5.154 5.859-8.768C14.5 2.964 11.659 0 8.033 0' fill='%231E1E1E'/%3E%3Cpath fill-rule='evenodd' clip-rule='evenodd' d='M8 4.5a2 2 0 1 0 .001 4.001A2 2 0 0 0 8 4.5' fill='%231E1E1E'/%3E%3C/svg%3E%0A");
    height: 16px;
    left: 16px;
    position: absolute;
    top: 0px;
    visibility: hidden;
    width: 16px;

    &.pinned {
      visibility: visible;
    }
  }

  &.wide {
    .jump-button {
      width: 58px;
    }

    .flag {
      left: 66px;
    }

    .pin {
      left: 24px;
    }
  }

  &.compact {
    padding: 16px 8px 8px 8px;

    .jump-button {
      font-size: 19px;
      height: 29px;
      padding: 1px 0 0 1px;
      width: 29px;
    }

    .flag {
      left: 29px;
    }

    &.wide {
      .jump-button {
        width: 46px;
      }

      .flag {
        left: 46px;
      }
    }
  }
}

