730:
.calculator-rnd {
  z-index: 1500;
  transform: none !important;

  &.hidden {
    display: none;
  }

  .title-container {
    background-color: #1e1e1e;
    color: #f7f7f7;
    width: 100%;
    padding: 5px 6px 5px 12px;
    margin-bottom: -1px;
    display: flex;
    flex-direction: row;
    justify-content: space-between;
    user-select: none;

    @media (forced-colors: active) {
      forced-color-adjust: none !important;
    }

    &:hover {
      cursor: grab !important;
    }

    &:active {
      cursor: grabbing !important;
    }

    .left-section {
      display: flex;
      align-items: center;
      flex-basis: 50%;
      flex-grow: 1;

      .title {
        height: 32px;
        font-family: Roboto, serif;
        font-size: 16px;
        font-weight: bold;
        font-stretch: normal;
        font-style: normal;
        line-height: 2;
        letter-spacing: 0.15px;
      }
    }

    .drag-handle-button {
      margin-left: 5px;
      background-color: inherit;
      color: #f0f0f0;
      line-height: 0px;
      font-size: 24px;
      font-weight: bold;
      letter-spacing: 1px;
      border-radius: 5px;
      height: 28px;
      width: 34px;
      text-align: center;
      vertical-align: middle;
      margin-top: 2px;
      margin-bottom: 3px;
      overflow: hidden;
      border: none;
      padding: 0 0 2px 1px;

      &:hover {
        cursor: grab !important;
      }

      &:active {
        cursor: grabbing !important;
      }

      &:focus {
        outline-color: #f0f0f0 !important;
        outline-style: solid !important;
        outline-width: 2px !important;
        outline-offset: 2px !important;
      }

      &:hover {
        background-color: #505050;
        cursor: pointer;
      }

      &.pressed:focus,
      &.pressed:hover {
        color: white;
        background-color: #888;
        outline-color: #f0f0f0 !important;
        outline-style: solid !important;
        outline-width: 2.5px !important;
        outline-offset: 2px !important;
      }
    }

    .right-section {
      display: flex;
      align-items: center;
      flex-basis: 50%;
      flex-grow: 1;
      text-align: center;
      justify-content: flex-end;
      font-family: Roboto, serif;
      font-size: 20px;
      font-weight: bold;
      font-stretch: normal;
      font-style: normal;
      line-height: 1.5;
      letter-spacing: 0.15px;

      .expand-collapse-button {
        border-style: none;
        padding: 0;
        border-radius: 7px;
        margin-right: 8px;
        height: 32px;
        width: 32px;
        background-color: inherit;
        font-family: Roboto, serif;
        font-size: 16px;
        font-weight: bold;
        font-stretch: normal;
        font-style: normal;
        line-height: 1.5;
        letter-spacing: 0.15px;
        color: #f7f7f7;
        padding-bottom: 2px;

        &:focus {
          outline-color: #f0f0f0 !important;
          outline-style: solid !important;
          outline-width: 2px !important;
          outline-offset: 0px !important;
        }

        &:hover {
          background-color: #505050;
        }

        & img {
          -webkit-user-drag: none;
        }
      }

      .closer {
        cursor: pointer;
        display: flex;
        justify-content: center;
        align-items: center;
        font-weight: normal;
        margin-left: 8px;
        height: 32px;
        width: 32px;
        border-radius: 7px;
        margin-right: 8px;
        padding-left: 1px;

        &:hover {
          background-color: #505050;
        }

        &:focus {
          outline-color: #f0f0f0 !important;
          outline-style: solid !important;
          outline-width: 2px !important;
          outline-offset: 0px !important;
        }
      }
    }
  }

  &.calculator-narrow {
    .title-container {
      padding-left: 4px;
    }
  }

  .calculator-content {
    position: relative;

    #calculator {
      width: 100%;
      height: 100%;
    }

    .calculator-loading-overlay {
      position: absolute;
      inset: 0;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      background: #f0f0f0;
      z-index: 2;
    }
  }

  /*
    in this file we currently set box-sizing to content-box for the desmos calculator container to fix an
    issue with the border covering the blue border around a selected item. This causes the graphing calc's
    width to be a px or 2 more than it should be, which is very noticeable when the loading overlay is present.
    this trims those edges from the graphing calc when loading.  remove once desmose fixes the underlying bug.
  */
  &.calculator-loading .calculator-content {
    overflow: hidden;
  }

  &.calculator-loading .resize-handle {
    visibility: hidden;
  }

  .resize-handle {
    @media (forced-colors: active) {
      forced-color-adjust: none !important;
    }
    width: 48px;
    height: 48px;
    border-radius: 24px;
    transform: translate(-12px, -12px);
    padding: 0px;
    background: transparent;
    border: none;
    cursor: grab;

    .resize-icon-wrapper {
      margin: auto;
      width: 24px;
      height: 24px;
      border-radius: 12px;
      border: 1px solid #b2b2b2;
      background: white;
      position: relative;
      stroke: #1e1e1e;
      z-index: 15;

      .resize-icon {
        position: relative;
        bottom: 2px;
      }
    }

    &:hover {
      .resize-icon-wrapper {
        background: #d9d9d9;
        .resize-icon {
          background: #d9d9d9;
        }
      }
    }

    &:active,
    &:focus {
      outline: none;

      .resize-icon-wrapper {
        outline: 2px solid #324dc7;
        outline-offset: 2px;
      }
    }

    &.pressed:active,
    &.pressed:focus {
      .resize-icon-wrapper {
        outline: 2.5px solid #324dc7;
        background-color: #b2b2b2;
        .resize-icon {
          background: #b2b2b2;
        }
      }
    }
  }

  #calculator.hidden {
    display: none;
  }

  // This fixes the desmos calculator's border from covering the blue border around
  // a selected item.  If desmos fixes this issue and we remove this, also remove the
  // related overflow:hidden style on the .calculator-loading class above.
  .dcg-container {
    box-sizing: content-box;
  }
}

