// AP Computer Science A styles (namespaced under .ap-cs-a). Ported from
// ref-sheet-content/preview/styles/cs.css so the hybrid JSON renderer
// matches the legacy HTML rendering of code, pretext, and table content.

code {
  font-family: "Courier Prime" !important;
  font-size: 14px;
  line-height: 1em;
  background-color: #e5e5e5;
  border: 1px solid #d9d9d9;
  border-radius: 4px;
  padding: 1px 1px 0px 1px;
}

.pretext code {
  font-family: "Courier Prime" !important;
  white-space: nowrap;
  border: none !important;
}

td.explanation {
  font-family: "Noto Serif";

  code {
    background-color: #e5e5e5;
    font-family: "Courier Prime" !important;
    font-size: 14px;
    padding: 1px 1px 0px 1px;
    border-radius: 4px;
    border: 1px solid #d9d9d9;
  }
}

table.cb-table {
  border: 1px solid #888888;
  border-collapse: collapse;

  th,
  td {
    border: 1px solid #888888;
  }
}

table td {
  font-size: 14px;
  line-height: 24px;
  width: 50%;

  pre {
    margin: 0;
  }

  .pretext {
    background-color: #e5e5e5;
    border: 1px solid #d9d9d9;
    border-radius: 4px;
    padding: 12px;
  }

  pre .pretext {
    margin: 8px 0 0 0;
    padding: 12px 12px 12px 0;

    code {
      padding: 12px;
    }
  }
}

// Pretext / codeblock spans render as block-level boxes so multi-line
// pseudocode lays out vertically (matches source CSS).
span.pretext,
span.codeblock {
  display: block;
}

span.codeblock code {
  padding-left: 12px;
}

