.directions-container,
.break-room-container {
  h1 {
    font-size: 32px;
    font-weight: 500;
    line-height: normal;
  }

  h2 {
    font-size: 19px;
    font-weight: 500;
    line-height: 1.14;

    margin-top: 8px;
    margin-bottom: 16px;
  }

  .student-name {
    font-family: Roboto;
    font-size: 21px;
    font-weight: 500;
    text-align: left;
    color: #fff;
    margin: 5.5px 0px 5.5px 0px;
    position: absolute;
    bottom: 24px;
    left: 0;
    padding-left: 48px;
    padding-right: 30px;
    max-width: 50%;
  }
}

.break-room-container {
  background-color: #1e1e1e;

  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;

  height: 100vh;
  width: 100vw;

  font-family: Roboto;
  line-height: normal;
  color: #fff;
  font-stretch: normal;
  font-style: normal;
  letter-spacing: normal;

  text-align: left;

  ::-webkit-scrollbar-track:hover {
    background-color: #505050;
    border: none !important;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #f0f0f0;
  }

  .bounding-box {
    width: 100%;
    height: 100%;

    display: flex;

    // we use reverse here because the content-box div needs to come first in the DOM for a11y.
    flex-direction: row-reverse;

    justify-content: space-between;

    .timer-box {
      height: 100%;
      width: 50%;

      .timer-border {
        position: relative;
        top: 50%;
        left: 50%;
        transform: translate(-50%, -50%);
        width: 274px;
        height: 128px;
        padding: 13px 25px 12px;
        border-radius: 8px;
        border: solid 1px #fff;

        &.no-text {
          padding-top: 21px;
        }

        section {
          .time {
            font-size: 72px;
            font-weight: 500;
            text-align: center;
          }
        }
      }
    }

    .content-box {
      overflow-y: auto;
      padding-right: 40px;
      margin-top: auto;
      margin-bottom: auto;
      width: 50%;

      &.time-out {
        width: 100% !important;

        .content-container {
          max-width: 100% !important;
        }
      }

      .content-container {
        max-width: 368px;
        flex-grow: 0;
        margin: 24px 29px 32px 0;
        font-family: Roboto;
        font-size: 16px;
        color: #fff;
        font-weight: normal;

        .break-content-container {
          hr {
            border: none;
            height: 1px;
            background-color: #ffffff;
            margin-top: 30px;
            margin-bottom: 28px;
          }
        }

        .message {
          max-width: 368px;
          font-size: 16px;

          // content from CMS comes wrapped in a p that is styled by Apricot so we need to override
          p {
            font-size: 16px;
          }

          line-height: 1.5;
          color: #fff;

          margin-top: 24px;
          margin-bottom: 16px;

          &.last {
            margin-bottom: 30px;
          }

          &.last-short {
            margin-bottom: 80px;
          }

          ol,
          ul {
            padding-left: 24px;

            li {
              padding-top: 14px;
            }
          }
        }

        .message-return-from-break {
          font-size: 20px;

          line-height: 1.6;
          color: #fff;

          margin-top: 16px;
          margin-bottom: 30px;
          font-weight: 300;

          &.last {
            margin-bottom: 36px;
          }
        }

        .rule {
          font-size: 14px;
          line-height: 1.5;

          margin-top: 11px;
          margin-bottom: 11px;

