        .break-room-list {
          font-family: Roboto;
          font-size: 19px;
          line-height: 1.11;
          color: #fff;
          padding-left: 0px;
          margin-left: 0;
          font-weight: normal;
        }

        .break-room-list-schoolday {
          font-family: Roboto;
          font-size: 19px;
          max-width: 368px;
          line-height: 1.11;
          color: #fff;
          padding-left: 0px;
          margin-left: 0;
        }
        .break-room-ol {
          padding-left: 30px;
          font-weight: normal;

          li {
            line-height: 1.5;
            font-size: 16px;
            padding-top: 10px;
          }
        }
        .break-room-list-message {
          font-weight: bold;
        }
      }
    }
  }

  &.center {
    text-align: center;

    .bounding-box {
      .content-box {
        margin-left: 0;
        margin-right: 0;
        padding-left: 0;
        padding-right: 0;

        .content-container {
          margin-left: 0;
          margin-right: 0;
          padding-left: 0;
          padding-right: 0;
        }
      }
    }
  }

  .remaining-break-time {
    font-family: Roboto;
    font-size: 19px;
    font-weight: bold;
  }

  .yellow-btn {
