  }

  .practice-resume-container {
    position: relative;
    top: 38px;
    width: 100%;
    text-align: center;
  }

  // this section resizes the timer and its containers/text/button to retain semi-consistent size when zooming
  @media (max-width: 820px) {
    .bounding-box {
      .timer-box {
        .timer-border {
          width: 226px;
          height: 107px;
          padding: 10px 18px 9px;
          border-radius: 7px;

          section {
            .time {
              font-size: 60px;

              .remaining-break-time {
                font-size: 15px;
              }
            }
          }

          &.no-text {
            padding-top: 17px;
          }

          .practice-resume-container {
            top: 35px;

