              font-size: 13px;
            }
          }
        }
      }
    }
  }
  @media (max-width: 704px) {
    .bounding-box {
      .timer-box {
        width: 48%;
      }

      .timer-box {
        .timer-border {
          width: 192px;
          height: 91px;
          padding: 8px 17px 8px;
          border-radius: 6px;

          section {
            .time {
              font-size: 50px !important;

              .remaining-break-time {
                font-size: 12px;
              }
            }
          }

          &.no-text {
            padding-top: 14px;
          }

          .practice-resume-container {
            top: 33px;

            .yellow-btn {
              font-size: 12px;
              padding-left: 15px;
              padding-right: 15px;
              padding-top: 11px;
              padding-bottom: 11px;
            }
          }
        }
      }
      .content-box {
        width: 52%;
        height: 100vh;
        padding-top: 10%;
      }
    }
  }
  @media (max-width: 586px) {
    .bounding-box {
      .timer-box {
        width: 47%;

        .timer-border {
          width: 166px;
          height: 77px;
          padding: 7px 15px 7px;
          border-radius: 6px;

          section {
            .time {
              font-size: 46px !important;

              .remaining-break-time {
                font-size: 10px;
              }
            }
          }
          &.no-text {
            padding-top: 12px;
          }

          .practice-resume-container {
            top: 28px;

            .yellow-btn {
              font-size: 12px;
              padding-left: 13px;
              padding-right: 13px;
              padding-top: 10px;
              padding-bottom: 10px;
            }
          }
        }
      }

      .content-box {
        width: 53%;
        height: 100vh;
        padding-top: 10%;
      }
    }
  }
  @media (max-width: 512px) {
    .bounding-box {
      .timer-box {
        width: 45%;

        .timer-border {
          width: 138px;
          height: 63px;
          padding: 5px 13px 6px;
          border-radius: 5px;

          section {
            .time {
              font-size: 40px !important;

              .remaining-break-time {
                font-size: 9px;
              }
            }
          }

          &.no-text {
            padding-top: 8px;
          }

          .practice-resume-container {
            top: 22px;

            .yellow-btn {
              font-size: 12px;
              padding-top: 8px;
              padding-bottom: 8px;
              padding-left: 10px;
              padding-right: 10px;
            }
          }
        }
      }

      .content-box {
        width: 55%;
        height: 100vh;
        padding-top: 10%;
      }
    }
  }

  // special scroll handling
  @media (max-height: 760px) {
    .bounding-box {
      .content-box {
        //this is done for some widths and also for some heights, to try to catch any scenario that could push
        // the text out of view without providing a scrollbar
        height: 100vh;
        padding-top: 10%;
      }
    }
  }

  // stack layout for smaller widths
  @media (max-width: 704px) {
    justify-content: start;

    .bounding-box {
      height: calc(100% - 30px);
      flex-direction: column-reverse;
      overflow: scroll;
      padding-bottom: 118px;

      .content-box {
        width: 100%;
        overflow-y: unset;
        padding-right: 0;
        margin-top: 0;
        margin-bottom: 0;
        text-align: center;

        &.practice {
          padding-top: 120px;
        }

        .content-container.content {
          text-align: left;
        }

        .content-container {
          max-width: 448px;
          margin-left: auto;
          margin-right: auto;
          margin-top: 40px;

          .message,
          .break-room-list-schoolday {
            max-width: 448px;
          }

          .break-content-container {
            padding-left: 16px;
            padding-right: 16px;
          }
        }

        .student-name {
          font-size: 21px;
          max-width: 100%;
          width: 100%;
          background-color: #1e1e1e;
          z-index: 2;
          overflow-x: visible;
          height: 32px;
          padding-top: 2px;
          bottom: 0px;
        }
      }

      .timer-box {
        width: 100%;
        height: 66px;
        padding-top: 70px;

        .timer-border {
          transform: translate(-50%, -30%);
        }
      }
    }
  }
}

