@import "./variables";
.mc-option-container {
  height: 100%;

  &.eliminated {
    .mc-custom-option:after {
      position: absolute;
      left: -5px;
      top: calc(50% - 1px);
      height: 2px;
      width: calc(100% + 10px);
      content: "";
      background: #505050;
      display: block;
    }
  }

  .mc-option {
    display: block;
    position: relative;
    cursor: pointer;
    font-size: 16px;
    color: $fontColorAlt;
    height: 100%;

    input {
      position: absolute;
      opacity: 0;
      cursor: pointer;

      // opacity 0 makes the actual input element invisible, but we still need it the proper size and z-index for mac text to speech functionality
      width: 25px;
      height: 25px;
      z-index: 1;

      &:checked {
        cursor: default;

        ~ .mc-custom-option {
          background-color: $fontColorAlt2;
          color: #ffffff;
          cursor: default;
        }
      }
    }

    .mc-custom-option {
      position: absolute;
      top: 1px;
      left: 1px;
      height: 24px;
      width: 24px;
      line-height: 21px;
      background-color: #ffffff;
      border-radius: 50%;
      border: 2px solid $fontColorAlt;
      text-align: center;
      vertical-align: middle;
      font-size: 14px;
      font-family: Roboto;
      font-weight: bold;
      cursor: pointer;
    }
  }

  @media (forced-colors: active) {
    .mc-option {
      input:checked ~ .mc-custom-option {
        forced-color-adjust: none !important;
      }
    }
  }
}

