      font-size: 14px;
      line-height: 16px;
      min-height: 16px;
      font-weight: 400;
      color: #c7dbff;

      .preparing-label {
        @keyframes pulse-opacity {
          0%, 100% { opacity: 1; }
          50% { opacity: 0.5; }
