// AP Statistics styles (namespaced under .ap-statistics). Base sticky rules
// ported from Apricot since it's not loaded in the hybrid JSON renderer.
.cb-table-sticky-css {
  overflow: auto;
  display: block;
  width: 100%;
  border: 1px solid #d9d9d9;
  height: 484px;

  .cb-table {
    position: relative;
    border-spacing: 0;
    border-collapse: separate;

    > thead > tr > th,
    > thead > tr > td,
    > tbody > tr > th,
    > tbody > tr > td,
    > tfoot > tr > th,
    > tfoot > tr > td {
      border-top: 0;
      border-right: 0;
    }

    > thead > tr > th:first-child,
    > thead > tr > td:first-child,
    > tbody > tr > th:first-child,
    > tbody > tr > td:first-child,
    > tfoot > tr > th:first-child,
    > tfoot > tr > td:first-child {
      border-left: 0;
    }

    // Outer right edge (base rule zeros border-right on all cells).
    > thead > tr > th:last-child,
    > thead > tr > td:last-child,
    > tbody > tr > th:last-child,
    > tbody > tr > td:last-child,
    > tfoot > tr > th:last-child,
    > tfoot > tr > td:last-child {
      border-right: 1px solid #b2b2b2;
    }

    // GPU-promoted sticky thead. Column separator is a LEFT inset shadow
    // so its x-position matches body cells (which use border-left on the
    // right cell of each boundary). A right inset would jog 1px left.
    thead.cb-active-header tr th {
      position: sticky;
      z-index: 3;
      top: 0;
      left: 0;
      background: #f0f0f0;
      transform: translateZ(0);
      will-change: transform;
      border: 0;
      box-shadow: inset 1px 0 0 #b2b2b2, inset 0 -1px 0 #b2b2b2;
    }

    // No left separator on the outer edge.
    thead.cb-active-header tr th:first-child {
      box-shadow: inset 0 -1px 0 #b2b2b2;
    }

    // Outer right edge uses a real border so the line sits at the edge.
    thead.cb-active-header tr th:last-child {
      border-right: 1px solid #b2b2b2;
    }

    // Sticky-left col 1 needs its separator on the RIGHT to match body col 1.
    thead.cb-active-header tr th.cb-active-column {
      z-index: 4;
      box-shadow: inset -1px 0 0 #b2b2b2, inset 0 -1px 0 #b2b2b2;
    }

    // Col 2 drops its left inset to avoid doubling col 1's right inset
    // (mirrors the body rule below).
    thead.cb-active-header tr th.cb-active-column + th {
      box-shadow: inset 0 -1px 0 #b2b2b2;
    }

    // Sticky body col 1. Inset shadows (not borders) so separators stay
    // visible inside the GPU layer while other columns scroll under.
    tbody.cb-active-column tr th:nth-child(1),
    tbody.cb-active-column tr td:nth-child(1) {
      position: sticky;
      z-index: 3;
      top: 0;
      left: 0;
      background: #fff;
      transform: translateZ(0);
      will-change: transform;
      border: 0;
      box-shadow: inset -1px 0 0 #b2b2b2, inset 0 -1px 0 #b2b2b2;
    }

    // Last row: container border paints the bottom; drop the inset shadow.
    tbody.cb-active-column tr:last-child th:nth-child(1),
    tbody.cb-active-column tr:last-child td:nth-child(1) {
      box-shadow: inset -1px 0 0 #b2b2b2;
    }

    // Col 2 drops border-left to avoid doubling col 1's right inset.
    tbody.cb-active-column tr th:nth-child(2),
    tbody.cb-active-column tr td:nth-child(2) {
      border-left: 0;
    }
  }
}

// 2-row thead (table-b, table-c): pin row 1 to a fixed height and stick row 2
// flush below it. Hard-coded `top` alone isn't enough — cell height varies
// with font/padding, so we collapse padding into line-height for determinism.
$rs-stats-header-row-h: 40px;

.table-b.cb-table-sticky-css,
.table-c.cb-table-sticky-css {
  .cb-table {
    thead.cb-active-header tr:first-child th {
      top: 0;
      height: $rs-stats-header-row-h;
      box-sizing: border-box;
      padding-top: 0;
      padding-bottom: 0;
      line-height: $rs-stats-header-row-h - 2px; // 1px top/bottom border
      vertical-align: middle;
    }

    thead.cb-active-header tr:nth-child(2) th {
      top: $rs-stats-header-row-h;
    }
  }
}

div.stats-image-container {
  margin: 0;
  padding: 0;
}

// Footnote hanging indent (asterisk hangs left of the indented text block).
.cb-font-size-xsmall {
  font-size: 12px;
  line-height: 1.4;
  padding-left: 0.65em;
  text-indent: -0.65em;
}
.cb-font-weight-regular {
  font-weight: 400;
}

// Math definition paragraphs
p.math-definition {
  margin: 0.25em 0 !important;
  padding: 0.25em 0 !important;
  line-height: 1em !important;
}

p.math-definition-long {
  margin: 0.25em !important;
  padding: 0.25em !important;
}

h3.table-header {
  font-family: "Noto Serif";
  font-size: 15px;
  font-weight: bold;
  font-stretch: normal;
  font-style: normal;
  letter-spacing: normal;
  text-align: left;
  color: #1e1e1e;
  // Override UA h3 margins + line-height to match source spacing.
  margin: 16px 0 0;
  line-height: 1.2;
}

p.table-caption {
  font-family: Roboto;
  font-size: 12px;
  font-weight: normal;
  font-stretch: normal;
  font-style: normal;
  white-space: nowrap;
  overflow-x: auto;
}

// GPU compositing on equation SVGs (avoids reflow flicker).
div.equation-force-svg svg {
  will-change: transform;
  transform: translate3d(0, 0, 0);
}

