.animated-hourglass-container {
  position: relative;
  width: 100%;
  height: 137px;
  margin: 0 auto;

  .hourglass {
    position: relative;
    display: block;
    width: 84px;
    height: 100%;
    margin: 0 auto;

    #frame {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background-size: cover;
      background-position: center;
      background-repeat: no-repeat;
      background-image: url("./images/hourglass-frame.svg");
      z-index: 2;
    }
    /* stylelint-disable-next-line at-rule-no-vendor-prefix */
    @-webkit-keyframes fadeIn {
      0% {
        opacity: 0;
      }
      100% {
        opacity: 1;
      }
    }
    @keyframes fadeIn {
      0% {
        opacity: 0;
      }
      100% {
        opacity: 1;
      }
    }

    .animated-hourglass-cell {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background-size: cover;
      background-position: center;
      background-repeat: no-repeat;
      /* stylelint-disable-next-line property-no-vendor-prefix */
      -webkit-animation: fade 14s infinite;
      animation: fade 14s infinite;
      z-index: 3;
    }

    @media (prefers-reduced-motion: reduce) {
      .animated-hourglass-cell {
        animation: none;
      }
    }

    #step2,
    #step3,
    #step4 {
      opacity: 0;
    }

    #step1 {
      animation-delay: 0s;
      background-image: url("./images/hourglass-1.svg");
    }

    #step2 {
      background-image: url("./images/hourglass-2.svg");
      animation-delay: 3.5s;
    }

    #step3 {
      background-image: url("./images/hourglass-3.svg");
      animation-delay: 7s;
    }

    #step4 {
      background-image: url("./images/hourglass-4.svg");
      animation-delay: 10.5s;
    }
    /* stylelint-disable-next-line at-rule-no-vendor-prefix */
    @-webkit-keyframes fade {
      0% {
        opacity: 1;
      }
      18% {
        opacity: 1;
      }
      25% {
        opacity: 0;
      }
      93% {
        opacity: 0;
      }
      100% {
        opacity: 1;
      }
    }
    @keyframes fade {
      0% {
        opacity: 1;
      }
      18% {
        opacity: 1;
      }
      25% {
        opacity: 0;
      }
      93% {
        opacity: 0;
      }
      100% {
        opacity: 1;
      }
    }
  }

  .clouds-container {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    overflow: hidden;

    #clouds {
      z-index: 1;
      width: 1374px;
      height: 333px;
      background-repeat: repeat-x;
      background-image: url("./images/hourglass-clouds.svg");

      animation: slide 25s linear infinite;
    }

    @media (prefers-reduced-motion: reduce) {
      #clouds {
        animation: none;
      }
    }

    @keyframes slide {
      0% {
        transform: translate(-1374px);
      }
      100% {
        transform: translate(0);
      }
    }
  }
}

