3507:
// AP Computer Science Principles styles (namespaced under .ap-cs-principles).
// Ported from ref-sheet-content/preview/styles/cs.css so the hybrid JSON
// renderer matches the legacy HTML rendering of code, pretext, codeblocks,
// procedure/statement boxes, and table content.

// Apricot reboot subset — the dev HTML preview loads Apricot CSS globally
// (box-sizing: border-box + body line-height), so reproduce here to match
// the dev source of truth.
*,
*::before,
*::after {
  box-sizing: border-box;
}

// Apricot utility classes used inline in the CSP content HTML. Apricot CSS
// isn't loaded by the hybrid JSON renderer, so reproduce the subset we need.
.cb-border {
  border: 1px solid #1e1e1e;
}
// `.cb-border` spans render inline by default in Apricot, but the parent
// `<code>` forces `line-height: 1em` which leaves no leading. The inline
// border then hugs Courier Prime's font content-area (ascent + descent),
// which is visibly asymmetric (less space below than above). Promote to
// `inline-block` with symmetric vertical padding and middle-baseline
// alignment so the box centers on neighboring text instead of tracking
// font metrics.
span.cb-border {
  display: inline-block;
  line-height: 1;
  padding-top: 2px;
  padding-bottom: 2px;
  vertical-align: middle;
}
.cb-border-2 {
  border-width: 2px;
}
.cb-black1-border {
  border-color: #1e1e1e;
}
.cb-border-radius-8 {
  border-radius: 8px;
}
.cb-border-radius-16 {
  border-radius: 16px;
}
.cb-padding-4 {
  padding: 4px;
}
.cb-padding-left-4 {
  padding-left: 4px;
}
.cb-padding-right-4 {
  padding-right: 4px;
}
.cb-margin-top-8 {
  margin-top: 8px;
}
.cb-margin-bottom-8 {
  margin-bottom: 8px;
}
.cb-margin-left-24 {
  margin-left: 24px;
}

& {
  font-family: "notoSerif", "noto-serif", "Noto Serif";
  background-color: #f0f0f0;
  font-size: 15px;
  line-height: 1.5;
}

// Group `header` text (e.g. "For all list operations…", "If the robot
// attempts to move…") is descriptive prose, not a heading — render it as
// normal weight (the shared `.rs-panel-header { font-weight: bold }` rule
// in reference-sheet.scss treats it as a title).
.rs-panel-header {
  font-weight: normal !important;
}

code {
  font-family: "Courier Prime" !important;
  font-size: 14px;
  line-height: 1em;
}

.pretext code {
  font-family: "Courier Prime" !important;
  white-space: nowrap;
  border: none !important;
}

td.explanation {
  font-family: "Noto Serif";

  code {
    background-color: #e5e5e5;
    font-family: "Courier Prime" !important;
    font-size: 14px;
    padding: 1px 1px 0px 1px;
    border-radius: 4px;
    border: 1px solid #d9d9d9;
  }
}

table.cb-table {
  border: 1px solid #888888;
  border-collapse: collapse;

  th,
  td {
    border: 1px solid #888888;
  }
}

table td {
  font-family: "Noto Serif";
  line-height: 24px;
  width: 50%;
  vertical-align: top;

  pre {
    margin: 0;
  }

  .pretext {
    background-color: #e5e5e5;
    border: 1px solid #d9d9d9;
    border-radius: 4px;
  }

  pre .pretext {
    margin: 8px 0 0 0;
    padding: 12px 12px 12px 0;
    line-height: 14px;

    code {
      background-color: #e5e5e5;
      padding: 0px 12px;
      line-height: 24px;
    }
  }

  // Codeblocks: full-width grey background to avoid ragged right margin.
  // Left padding lives on the block-level `<span class="codeblock">` (not the
  // inline `<code>` child) so every line inside the codeblock is indented
  // equally — inline `padding-left` on `<code>` would only indent the first
  // line, leaving subsequent `\n`-separated lines flush left.
  pre span.codeblock {
    padding: 12px 12px 16px 12px;
    background-color: #e5e5e5;
    border: 1px solid #d9d9d9;
    border-radius: 4px;
    margin: 8px 0 0 0;
  }

  div.svg-container svg {
    height: fit-content;
    margin-top: -16px;
  }
}

span.pretext,
span.codeblock {
  display: block;
}

// Assignment-expression SVG sizing adjustment
div.svg-container#assignment-expression svg {
  margin-left: -24px;
  transform: scale(0.8);
}

// Accordion panel background tweak
.cb-accordion
  .cb-accordion-panels
  .cb-accordion-container
  .cb-accordion-panel {
  overflow-y: hidden !important;
  background-color: #f5f5f5;
}

// Procedure block (boxed pseudocode)
.procedure-box {
  background-color: #d9d9d9;
  border: 2px solid black;
  border-radius: 8px;
  padding: 8px;
  width: fit-content;

  // <code> is inline by default; force block so its `.row` flex child
  // establishes a proper line box.
  > code {
    display: block;
  }

  // Bootstrap/Apricot `.row` + `.col` aren't loaded; the PROCEDURE block
  // relies on them to lay out the "PROCEDURE procName" label beside the
  // parameter-list box. Reproduce a minimal flex row scoped to procedure-box
  // so the contents don't stack vertically and look jumbled.
  .row {
    display: flex !important;
    flex-direction: row;
    flex-wrap: nowrap;
    align-items: flex-start;
    gap: 8px;
  }
  .col {
    display: block;
    flex: 0 0 auto;
  }
}

.procedure-list {
  display: inline-block;
  vertical-align: top;
}

div .procedure-list {
  margin-left: 4px;
  margin-bottom: 8px;
  padding: 0 4px;
}

.statement-box {
  background-color: white;
  border: 2px solid black;
  border-radius: 8px;
  padding: 4px;
  width: fit-content;
  white-space: nowrap;
}

// Custom scroll
.ap-custom-scroll {
  width: 99%;
  overflow-y: hidden;
}

// Responsive columns: unconditionally override the bootstrap-style
// col-md-* max-width constraint inside CSP ref-sheet content.
.col-md-3,
.col-md-4 {
  max-width: none;
}

.cb-scrollbar-container {
  &:not(.active) {
    height: fit-content;

    .cb-table-responsive {
      height: fit-content !important;
    }
  }

  &.active {
    margin-bottom: 0;
  }
}

