        display: none;
      }
    }

    :global(.viewable) {
      max-height: var(--preview-max-height);
      overflow: hidden;
      border: 1px solid #b2b2b2;

      :global(.bezel) {
        width: 100%;
        height: 100%;
        padding: var(--preview-bezel-size);
        overflow: hidden;

        img,
        svg {
          transform-origin: 0 0;
        }
        :global(.story_narration) {
          img {
            min-width: 0;
            min-height: 0;
            height: auto;
          }
        }
      }
    }
  }

  :global(.lightbox) {
    --fullscreen-padding: 40px;
    display: none;
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    z-index: 1000;
    touch-action: none;

    &:global(.compare) {
      :global(.story_narration) {
        aspect-ratio: auto !important;
      }
    }

    :global(.frame) {
      flex-direction: column;
    }

    :global(.overlay) {
      display: flex;
      justify-content: center;
      align-items: center;
      background: rgba(0, 0, 0, 0.5);
      touch-action: none;

      width: 100%;
      height: 100%;

      :global(.viewable) {
        :global(.story_narration) {
          aspect-ratio: 1 / 1;
          max-width: max(100vw - 80px) !important;
          max-height: max(100vh - 80px) !important;

          img {
            max-width: auto;
            max-height: auto;
          }
        }

        :global(.compare) {
          gap: 16px;
          grid-template-columns: auto auto;
          aspect-ratio: unset;

          *:nth-child(odd) {
            justify-self: end;
          }

          *:nth-child(even) {
            justify-self: start;
          }
        }

        svg,
        img {
          background: #fff;
        }
      }
    }

    :global(.controls) {
      background: #505050;
      display: inline-flex;
      position: absolute;
      top: 8px;
      right: 40px;
      align-items: center;
      justify-content: center;
      color: #d1d1d1;
      padding: 0;
      z-index: 100;

      p {
        color: #fff;
      }

      button {
        display: flex;
        padding: 0 8px;
        justify-content: center;
        align-items: center;
        background: none;
        color: #fff;
        border: 0;
        margin: 0;

        &:disabled {
          color: #d1d1d1;
        }

        &:active,
        &:focus {
          outline: 2px solid #fff;
          color: #fff;
        }

        &:hover {
          color: #fff;
          background: #6b6b6b;
          text-decoration: none;
        }
      }

      button[name="fullscreen"],
      button[name="compare"] {
        display: none;
      }
    }
  }

  &:global(.fullscreen) {
    :global(.lightbox) {
      display: flex;
    }
  }
}

