#virtual-keypad {
  box-sizing: border-box;

  width: 284px;
  height: 200px;

  padding: 8px;

  display: grid;
  grid-template-columns: 84px 84px 84px;
  grid-template-rows: min-content min-content min-content min-content;
  column-gap: 8px;
  row-gap: 8px;
  justify-items: center;
  align-items: center;

  overflow: hidden !important;

  button {
    box-sizing: border-box;
    font-family: "Roboto", "Roboto Regular", sans-serif;
    line-height: 39px;
    letter-spacing: -0.1px;
    width: 84px;
    height: 40px;
    font-size: 32px;
    border-radius: 8px;
    text-align: center;
    vertical-align: center;
    padding: 0;
    margin: 0;
    box-shadow: 0 3px 3px 0 rgba(0, 0, 0, 0.17);
    border: solid 1px #d9d9d9;
    background-color: #fff;

    &:hover {
      background-color: #f0f0f0;
    }

    &:active {
      border: solid 1px #888888;
      background-color: #d9d9d9;
    }

    &.backspace {
      display: grid;
      align-items: center;
      justify-items: center;

      svg {
        width: 28px;
        height: 18px;
      }

      .backspace-icon-component {
        fill: #1e1e1e;
        @media (forced-colors: active) {
          fill: #fff;
        }
      }
    }
  }

  div {
    box-sizing: border-box;
    width: 84px;
    text-wrap: nowrap;

    .small {
      width: 40px;
      display: inline-block;

      svg {
        margin-top: -5px;
      }
    }

