.highlightable {
  $referenceTextBgColor: #ececec;

  .passage_reference_highlight {
    text-decoration-line: underline;
    text-decoration-thickness: 1px !important;
    text-underline-offset: 2px;
    background-color: $referenceTextBgColor;
  }

  &.package-flag-enabled.highlight-mode {
    cursor:
      url("data:image/svg+xml;base64,")
        0 2,
      text;
  }

  &.highlight-mode {
    img {
      cursor: not-allowed;
    }
  }

  .highlighted {
    @media (forced-colors: active) {
      mix-blend-mode: normal !important;
      border-bottom-style: solid;
    }

    --highlight-color-1: #fff4b1;
    --highlight-hover-color-1: #fedb00;
    --highlight-dialog-open-color-1: #fedb00;
    --highlight-color-2: #d1ebff;
    --highlight-hover-color-2: #91cdfa;
    --highlight-dialog-open-color-2: #91cdfa;
    --highlight-color-3: #ffd5f4;
    --highlight-hover-color-3: #f799de;
    --highlight-dialog-open-color-3: #f799de;

    mix-blend-mode: darken;
    border-bottom-style: none;
    border-bottom-width: 1px;
    border-bottom-color: black;
    scroll-margin: 4px;
    background-color: var(--highlight-color-1);
    margin-bottom: 0px;

    &.underline-style-1 {
      margin-bottom: -1px;
      border-bottom-style: solid;
    }
    &.underline-style-2 {
      border-bottom-style: dashed;
      margin-bottom: -1px;
    }
    &.underline-style-3 {
      border-bottom-style: dotted;
      border-bottom-width: 2px;
      margin-bottom: -2px;
    }

    &.highlight-color-2 {
      background-color: var(--highlight-color-2);
    }
    &.highlight-color-3 {
      background-color: var(--highlight-color-3);
    }
    &.highlight-hover {
      background-color: var(--highlight-hover-color-1);

      &.highlight-color-2 {
        background-color: var(--highlight-hover-color-2);
      }
      &.highlight-color-3 {
        background-color: var(--highlight-hover-color-3);
      }
      & > * {
        background-color: transparent !important;
      }
    }
    &.highlight-annotations-open {
      background-color: var(--highlight-dialog-open-color-1);
      &.highlight-color-2 {
        background-color: var(--highlight-dialog-open-color-2);
      }
      &.highlight-color-3 {
        background-color: var(--highlight-dialog-open-color-3);
      }
      & > * {
        background-color: transparent !important;
      }
    }
  }
}

