.radio-toggle-container {
  display: flex;
  width: 100%;
  height: 60px;
  background-color: #fff;
  flex-direction: row;
}
.radio-toggle-container.disabled {
  background-color: #f0f0f0;

  .radio-wrapper {
    label {
      &::before {
        border-color: #b2b2b2;
      }
    }
  }

  .sides {
    border-top: 1px solid #f0f0f0;

    &:last-child {
      border-left: 1px solid #f0f0f0;
    }
  }
}

@media (forced-colors: active) {
  .radio-toggle-container {
    forced-color-adjust: none !important;
  }
}

.sides {
  &:first-child {
    border-right: 1px solid #cccccc;
  }
  &:last-child {
    border-left: 1px solid #cccccc;
  }

  border-top: 1px solid #cccccc;
  display: flex;
  flex-direction: row;
  flex: 1;
  align-content: center;
  align-items: center;
  justify-content: center;
  height: 100%;
  text-decoration: none;

  fieldset {
    border: none;
  }

  .radio-wrapper {
    margin: 0.5rem 0;
  }

  input[type="radio"] {
    opacity: 0;

    + label {
      position: relative;
      cursor: pointer;

      &::before {
        content: "";
        position: absolute;
        left: -24px;
        top: 0;
        border-radius: 50%;
        border: 2px solid #505050;
        width: 24px;
        height: 24px;
      }

      &::after {
        content: "";
        position: absolute;
        left: -20px;
        top: 4px;
        border-radius: 50%;
        width: 16px;
        height: 16px;
      }
    }

    &:checked {
      + label::after {
        background: #324dc7;
      }
    }

    &:focus {
      + label::before {
        box-shadow: 0 0px 8px orange;
      }
    }
  }
}

