// AP Chemistry – Periodic Table (Adrian Roselli's CSS Grid layout)
// Targets: Safari 16+, Chrome latest
// Stripped: IE -ms-grid prefixes, float fallback, -ms-high-contrast queries

& {
  background: #fff;
}

#PeriodicTable {
  line-height: 1.4;
  color: #333;
  padding-top: 24px;
  min-width: 1000px;
  background: #fff;
  font-family: 'Noto Serif';

  .licensing {
    padding: 24px;
    font-size: 15px;
    font-weight: 400;
  }
}

#PeriodicTitle {
  font-family: "Noto Serif";
  padding-bottom: 24px;
  margin: -24px 0 24px 24px;
}

#Elements {
  margin-left: 12px;
  margin-right: 12px;

  ol {
    padding: 0;
    color: #000;
    margin: 2rem 0;
    font-size: 0.6em;
    display: grid;
    grid-template-columns: repeat(18, 5.56%);
  }

  li {
    list-style-type: none;
    outline: .1em solid #000;
    box-sizing: border-box;
    padding: .5em .75em;
    width: 100%;
    position: relative;
    overflow: hidden;
    transition: transform .05s ease-in-out, box-shadow .2s ease-in-out, background-color .2s ease-in-out;
    margin-bottom: 0 !important;

    div {
      text-align: center;

      &:first-child {
        font-size: 150%;
      }

      &:not(.shortcut-key):nth-child(2) {
        font-size: 250%;
        font-weight: bold;
        line-height: 1.1;
      }

      &:nth-child(3) {
        font-size: 150%;
        line-height: 1.1;
      }
    }

    button {
      position: absolute;
      top: 0;
      left: 0;
      box-sizing: border-box;
      font: inherit;
      line-height: 1;
      padding: 0;
      text-indent: 5em;
      border: none;
      color: #fff;
      border-right: .1em solid #000;
      border-bottom: .1em solid #000;
      border-radius: 0 0 67% 0;
      width: 2em;
      height: 2em;
      overflow: hidden;
      background-color: #000;
      background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M71.77069 61.87311a36.53064 36.53064 0 1 0-9.89917 9.89868l21.1792 21.17792a6.9996 6.9996 0 1 0 9.89844-9.89942zM41.49994 64a22.5 22.5 0 1 1 22.5-22.5 22.52554 22.52554 0 0 1-22.5 22.5z' fill='%23fff'/%3E%3C/svg%3E");
      background-repeat: no-repeat;
      background-size: 1em 1em;
      background-position: 30% 40%;

      &:focus,
      &:hover {
        background-color: #fff;
        color: #000;
        outline: none;
        background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M71.77069 61.87311a36.53064 36.53064 0 1 0-9.89917 9.89868l21.1792 21.17792a6.9996 6.9996 0 1 0 9.89844-9.89942zM41.49994 64a22.5 22.5 0 1 1 22.5-22.5 22.52554 22.52554 0 0 1-22.5 22.5z' fill='%23000'/%3E%3C/svg%3E");
      }
    }

    &:not(#Key):hover,
    &:not(#Key):focus-within {
      transform: scale(2);
      z-index: 120;
      box-shadow: 0 0 1em rgba(0, 0, 0, .8);
    }
  }

  li#Key button {
    position: relative;
    border-radius: 0;
    border: none;
    height: 1.5em;
    width: 1.5em;
    background-color: transparent;
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M71.77069 61.87311a36.53064 36.53064 0 1 0-9.89917 9.89868l21.1792 21.17792a6.9996 6.9996 0 1 0 9.89844-9.89942zM41.49994 64a22.5 22.5 0 1 1 22.5-22.5 22.52554 22.52554 0 0 1-22.5 22.5z' fill='%23000'/%3E%3C/svg%3E");
    background-position: 100% 100%;

    &:focus,
    &:hover {
      background-color: #000;
      background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M71.77069 61.87311a36.53064 36.53064 0 1 0-9.89917 9.89868l21.1792 21.17792a6.9996 6.9996 0 1 0 9.89844-9.89942zM41.49994 64a22.5 22.5 0 1 1 22.5-22.5 22.52554 22.52554 0 0 1-22.5 22.5z' fill='%23fff'/%3E%3C/svg%3E");
    }
  }

  // Edge-column hover origin
  li.col1:hover,
  li.col1:focus-within {
    transform-origin: left;
  }

  li.col18:hover,
  li.col18:focus-within {
    transform-origin: right;
  }
}

// Element category colors (all white in exam context)
.cat-diatomic_nonmetal,
.cat-noble_gas,
.cat-alkali_metal,
.cat-alkaline_earth_metal,
.cat-metalloid,
.cat-polyatomic_nonmetal,
.cat-post-transition_metal,
.cat-transition_metal,
.cat-lanthanide,
.cat-actinide,
.cat-unknown_probably_transition_metal,
.cat-unknown_probably_post-transition_metal,
.cat-unknown_probably_metalloid,
.cat-unknown_predicted_to_be_noble_gas,
.cat-unknown_but_predicted_to_be_an_alkali_metal {
  background-color: white;
}

// Key / Legend
#Key {
  h2 {
    margin: 0 0 1em 0;
    font-size: 1.1em;
  }

  dl {
    line-height: 1.4;
    margin: 0;
    padding: 0;
    width: 100%;
    text-transform: capitalize;
    display: grid;
    grid-template-columns: repeat(2, 1em 12em);
    grid-gap: .5em 1em;
  }

  dt,
  dd {
    margin: 0;
    padding: 0;
  }

  dt {
    width: 1.5em;
    height: 1.5em;
    outline: .1em solid #000;
  }

  dt[class*=unknown],
  dt[class*=unknown] + dd {
    display: none;
  }

  // Key dl grid positioning
  dt:nth-of-type(2n-1) { grid-column: 1; }
  dt:nth-of-type(2n) { grid-column: 3; }
  dd:nth-of-type(2n-1) { grid-column: 2; }
  dd:nth-of-type(2n) { grid-column: 4; }

  dl *:nth-child(n+5) { grid-row: 2; }
  dl *:nth-child(n+9) { grid-row: 3; }
  dl *:nth-child(n+13) { grid-row: 4; }
  dl *:nth-child(n+17) { grid-row: 5; }
}

// Grid placement
li#Key {
  grid-row: 1 / 4;
  grid-column: 5 / 11;
  width: 100%;
  outline: none;
  padding-top: 1em;
}

li#Uue {
  background-color: transparent;
  outline: none;
  pointer-events: none;
}

li.shortcut {
  background-color: white;
  pointer-events: none;
}

div.shortcut-key {
  font-size: 150%;
  font-weight: normal !important;
  // DAPI-31952: source HTML overrides margin to align atomic numbers
  margin: 0px 0px 8px 0px !important;
}

div.shortcut-asterisk {
  font-size: 250% !important;
  line-height: 16px !important;
}

// DAPI-31952 Prevent wrapping and align atomic numbers for the transition metals
#Elements li[id="89-103"] {
  padding: 0.5em 0.68em !important;
}

// Column number headers
#Elements li#numeric1 {
  margin-top: -2.5em !important;
  margin-left: 0;
  padding-left: 1.1em;
}

#Elements li#numeric18 {
  margin-top: -2.5em !important;
  margin-left: 0;
  padding-left: 0.7em;
}

#Elements li:is(#numeric10, #numeric11, #numeric12, #numeric13, #numeric14, #numeric15, #numeric16, #numeric17) {
  margin-left: -4px;
}

#Elements li:is(#numeric2, #numeric3, #numeric4, #numeric5, #numeric6, #numeric7, #numeric8, #numeric9) {
  margin-left: 7px;
}

.Numeric {
  font-size: 19px;
  height: min-content;
  margin-top: 16px;
  outline: none !important;
  pointer-events: none;
  width: min-content;
  color: #6b6b6b;

  div {
    transform: rotate(0deg);
  }
}

// Row placement
li.row1 { grid-row: 1 / 2; }
li.row2 { grid-row: 2 / 3; }
li.row3 { grid-row: 3 / 4; }
li.row4 { grid-row: 4 / 5; }
li.row5 { grid-row: 5 / 6; }
li.row6 { grid-row: 6 / 7; }
li.row7 { grid-row: 7 / 8; height: 7.223em; }
li.row8 { grid-row: 8 / 9; }
li.row9 { grid-row: 9 / 10; }
li.row10 { grid-row: 10 / 11; }

#Actinoids { grid-column: 0; grid-row: 10; }
#Lanthanoids { grid-column: 0; grid-row: 9; }

li.chem-label {
  outline: none !important;
  padding: 0 !important;
  pointer-events: none;
  width: 16em !important;

  div {
    margin-top: 2.5em;
    transform: rotate(0deg);
    width: 14em;
    text-align: right;
  }
}

// Column placement
li.col1 { grid-column: 1 / 2; }
li.col2 { grid-column: 2 / 3; }
li.col3 { grid-column: 3 / 4; }
li.col4 { grid-column: 4 / 5; }
li.col5 { grid-column: 5 / 6; }
li.col6 { grid-column: 6 / 7; }
li.col7 { grid-column: 7 / 8; }
li.col8 { grid-column: 8 / 9; }
li.col9 { grid-column: 9 / 10; }
li.col10 { grid-column: 10 / 11; }
li.col11 { grid-column: 11 / 12; }
li.col12 { grid-column: 12 / 13; }
li.col13 { grid-column: 13 / 14; }
li.col14 { grid-column: 14 / 15; }
li.col15 { grid-column: 15 / 16; }
li.col16 { grid-column: 16 / 17; }
li.col17 { grid-column: 17 / 18; }
li.col18 { grid-column: 18 / 19; }

// Dialog / Overlay
#Overlay {
  position: absolute;
  z-index: 150;
  top: 0;
  bottom: 0;
  left: 0;
  right: 0;
  background-color: rgba(0, 0, 0, .75);
  display: none;
  backdrop-filter: blur(.1em);
}

[role="dialog"] {
  position: absolute;
  z-index: 200;
  top: 10vh;
  bottom: 10vh;
  left: 10vw;
  right: 10vw;
  max-width: 36rem;
  margin-left: auto;
  margin-right: auto;
  overflow: hidden;
  box-shadow: 0 0 2em rgba(0, 0, 0, .5);
  border: .1em solid #000;
  background: #fefefe;
  padding: 0;
  visibility: visible;
  transition: transform .1s ease-in, opacity .2s ease-in;

  &[hidden] {
    display: block;
    visibility: hidden;
    transform: scale(.5);
    opacity: .6;
  }

  h2 {
    margin: 0;
    padding: .5rem 1.25rem;
    background: #333;
    color: #fefefe;
  }

  button {
    float: right;
    margin: -2rem 1.25rem 0 0;
    padding: 0;
    text-indent: 5em;
    line-height: 0;
    font: inherit;
    background: transparent;
    border: none;
    border-radius: 50%;
    width: 1.5em;
    height: 1.5em;
    overflow: hidden;
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M50 0a50 50 0 1 0 0 100A50 50 0 0 0 50 0zm26.6 76.6a37.5 37.5 0 0 1-53.2 0 37.5 37.5 0 0 1 0-53.2 37.5 37.5 0 0 1 53.2 0 37.5 37.5 0 0 1 0 53.2zm-7.3-45.9a6.6 6.6 0 0 0-9.3 0l-10 10-10-10a6.6 6.6 0 0 0-9.3 9.3l10 10-10 10a6.6 6.6 0 1 0 9.3 9.3l10-10 10 10a6.6 6.6 0 0 0 9.3 0 6.6 6.6 0 0 0 0-9.3l-10-10 10-10a6.6 6.6 0 0 0 0-9.3z' fill='%23fff'/%3E%3C/svg%3E");
    background-size: 100%;
    background-repeat: no-repeat;
    background-position: 50%;

    &:focus,
    &:hover {
      outline: .2em solid transparent;
      background: #fff;
      background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Cpath d='M50 0a50 50 0 1 0 0 100A50 50 0 0 0 50 0zm26.6 76.6a37.5 37.5 0 0 1-53.2 0 37.5 37.5 0 0 1 0-53.2 37.5 37.5 0 0 1 53.2 0 37.5 37.5 0 0 1 0 53.2zm-7.3-45.9a6.6 6.6 0 0 0-9.3 0l-10 10-10-10a6.6 6.6 0 0 0-9.3 9.3l10 10-10 10a6.6 6.6 0 1 0 9.3 9.3l10-10 10 10a6.6 6.6 0 0 0 9.3 0 6.6 6.6 0 0 0 0-9.3l-10-10 10-10a6.6 6.6 0 0 0 0-9.3z' fill='%23000'/%3E%3C/svg%3E");
      box-shadow: 0 0 .5em rgba(255, 255, 255, 1);
    }
  }

  div[role=document] {
    display: inline;

    div {
      box-sizing: border-box;
      height: calc(100% - 3rem);
      overflow: auto;
      padding: .5rem 1.25rem;
    }
  }
}

@container reference-sheet (min-width: 30em) {
  [role="dialog"] dl {
    margin: 1em 2rem;
    column-count: 2;
    column-gap: 4rem;
  }
}

// Accessibility
@media screen and (prefers-reduced-motion: reduce) {
  #Elements li,
  [role="dialog"] {
    transition: none;
  }
}

// Print
@media print {
  #PeriodicTable {
    background-color: #fff;
    color: #000;
    font-size: 8pt;
  }

  a:link,
  a:visited,
  footer a:link,
  footer a:visited {
    color: #000;
  }

  #Elements li button {
    display: none;
  }

  #Elements ol {
    font-size: .7vw;
  }
}

@media print and (orientation: landscape) {
  #Elements ol {
    font-size: .63vw;
  }

  #Elements + h2 {
    page-break-before: always;
  }
}

