4840:
@import "../utility/variables";

.mcr-option-list-container {
  padding-bottom: 10px;

  .answer-wrapper-label {
    display: inline;

    .mcr-answer-container {
      position: relative;
      display: flex;
      align-items: center;
      white-space: nowrap;
      margin-top: 15px;
      border-radius: 8px;
      padding: 12px 24px 12px 56px;
      cursor: pointer;

      &:hover:not(:has(.option-eliminator:hover)) {
        background-color: #f0f0f0;
      }

      /**
        Set the background color to white for touch screens so they don't look "selected" if Show More is clicked.
        Touch devices fire a sticky :hover state on tap; hover: none + pointer: coarse targets touch screens only,
        avoiding false matches on Retina/HiDPI desktops and laptops.
      */
      @media (hover: none) and (pointer: coarse) {
        &:hover:not(:has(.option-eliminator:hover)) {
          background-color: #fff;
        }

        .border-box:hover {
          background-color: transparent;
        }
      }

      .border-box {
        position: absolute;
        width: 100%;
        height: 100%;
        top: 1px;
        left: 0;
        border: 1px solid #505050;
        border-radius: 8px;

        &.focus-outline {
          outline: -webkit-focus-ring-color auto 1px;
        }

        &.selected {
          border: 3px solid $fontColorAlt2;
        }

        &:hover {
          background-color: #f0f0f0;
        }
      }

      &.eliminated {
        &:after {
          position: absolute;
          left: -4px;
          top: 50%;
          height: 2px;
          width: calc(100% + 8px);
          content: "";
          background: #1e1e1e;
          display: block;
        }

        & > div:not(.option-eliminator, .border-box) {
          opacity: 0.5;

          /* safari incorrectly excludes position: absolute children from a parent's opacity
          compositing layer when a scroll container is present — transform: translateZ(0) forces
          the parent onto its own compositing layer, keeping the children in it. */
          transform: translateZ(0);
        }
      }

      &.show-option-eliminators {
        margin-right: 50px;
      }

      &.middle-aligned {
        align-items: center;
      }
      .label-option-container {
        position: absolute;
        top: 11px;
        left: 12px;
      }
      .label-radio-container {
        display: flex;
        align-items: center;

        .letter-label {
          font-size: 19px;
          width: 16px;
        }
      }

      .mcr-answer-text {
        white-space: normal;
        width: 100%;
        z-index: 1;
        // DAPI-33358: content wider than the option (e.g. very wide math
        // equations) scrolls horizontally within the option instead of
        // punching through the border. overflow-y is forced to `hidden`
        // because CSS coerces a `visible` axis to `auto` when the other axis
        // is non-visible, which would produce a spurious vertical scrollbar
        // from any minor baseline overshoot in the rendered math.
        overflow-x: auto;
        overflow-y: hidden;

        p {
          margin: 0;
          line-height: 1.5;
        }
        img.math-equation {
          margin-top: -1px;
          margin-bottom: 1px;
        }
      }
    }
  }
}

