5305:
.preferred-content-selector {
  display: flex;
  pointer-events: none;

  .preferred-content-selector-button-container {
    pointer-events: auto;
    position: relative;

    .preferred-content-selector-button,
    .preferred-content-selector-button * {
      text-decoration: none !important;
    }

    .preferred-content-selector-button.selected::after {
      content: "";
      position: absolute;
      bottom: 9px;
      left: 0;
      width: 100%;
      height: 2px;
      background-color: #1e1e1e;
    }

    button {
      height: auto;
      border-width: 2px;
      border-radius: 0px;
      box-shadow: none;
      align-items: flex-end;
      padding: 0;
      font-size: 12px;
      font-family: Roboto;
      font-weight: 500;
      letter-spacing: 0.01px;
      color: #1e1e1e;
      white-space: nowrap;
      padding-bottom: 1px;
      margin-bottom: 2px;

      img {
        width: auto;
        margin: 0;
      }

      &:hover {
        background: #f0f0f0;
        border: 2px solid #f0f0f0;
        text-decoration: none;
        box-shadow: none;
      }

      &:focus {
        border-width: 2px;
        box-shadow: none;
        text-decoration: none;
        border: 2px solid transparent;
      }

      .preferred-content-title {
        line-height: 18px;
      }

      .preferred-content-labels-container {
        display: flex;
        align-items: center;
        justify-content: center;
        height: 24px;
        overflow: hidden;

        img {
          padding: 0px 1px 0px 0px;
          margin-top: 2px;
        }
      }

      .cb-down,
      .cb-up {
        margin-left: 4px !important;
        line-height: 16px !important;
      }
    }
  }

  .preferred-content-selector-flyout {
    display: block;
    position: absolute;
    margin-top: 48px;
    min-width: 140px;
    width: max-content;
    pointer-events: auto;

    .cb-card {
      padding: 8px 0 !important;
      margin: 0;
      height: auto;
      border-radius: 8px;
      overflow-y: auto;
      overflow-x: hidden;
      font-size: 16px;
      font-family: "Roboto";

      ul {
        margin: 0;
        padding: 0;
      }

      .language-item {
        display: flex;
        align-items: center;
        padding: 0px;
        font-weight: normal;

        .language-item-button {
          position: relative;
          background: none;
          border: none;
          padding: 0;
          margin: 0;
          font: inherit;
          color: inherit;
          cursor: pointer;
          display: flex;
          width: 100%;

          > div:first-child {
            padding: 8px 8px 8px 16px;
          }

          > div:last-child {
            padding: 8px 16px 8px 0px;
          }

          &:focus-visible {
            outline-offset: -3px;
          }
        }

        &.selected {
          .language-item-button {
            background-color: #e6edf8;

            .language-item-label {
              font-weight: bold;
              text-decoration: underline;
              text-underline-offset: 1px;
            }
          }
        }

        &:hover {
          .language-item-button {
            background-color: #d9d9d9;
          }
        }

        &.selected,
        &:hover {
          .language-item-button {
            &::before {
              content: "";
              position: absolute;
              top: 0;
              left: 0;
              width: 2px;
              height: 100%;
              background-color: #1e1e1e;
            }
          }
        }
      }
    }
  }
}

