  top: 74px;
  left: 50%;
  transform: translate(-50%, 0);
  z-index: 1001;

  .toast {
    margin-top: 18px;
    padding-top: 15px;
    padding-bottom: 15px;
    padding-left: 21px;
    padding-right: 8px;
    display: flex;
    position: relative;
    cursor: default;
    vertical-align: middle;
    color: #ffffff;
    border-radius: 8px;
    box-shadow: 0 1px 10px 0 rgba(59, 59, 59, 0.24);
