      margin-top: 13px;
    }
  }

  .toast__message {
    float: left;
  }

  .toast__button {
    float: right;
    background-color: #1e1e1e;
    border: 0;
    text-align: right;
    color: #71c5e8;
    width: 54px;
    height: 24px;
  }

  .toast__close-btn {
    border: none;
    background-color: transparent;
    font-size: 28px;
    cursor: pointer;
    color: #ffffff;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    height: 100%;
  }

  .transition-enter {
    opacity: 0.1;
  }

  .transition-enter-active {
    opacity: 1;
    transition: all 400ms;
  }

  .transition-exit {
