  pointer-events: auto;

  button {
    height: 42px;
    color: #333;

    img {
      width: auto;
      margin-right: 8px;
    }

    border-width: 2px;
    border-radius: 4px;
    box-shadow: none;

    .audio-settings-button-content {
      text-decoration: none;

