.audio-settings-flyout {
  transform: translateZ(0); /* IMPORTANT to prevent Safari repaint issues! */
  display: block;
  position: absolute;
  margin-top: 48px;
  width: 246px;
  pointer-events: auto;
  z-index: 100;

  .cb-card {
    --widthOffset: 0px;
    padding: 16px !important;
    margin: 0 10px;
    height: auto;
    max-height: 528px;
    border-radius: 10px;
    overflow-y: auto;
    overflow-x: hidden;
  }

