    margin-bottom: 8px;
  }

  .cb-dropdown {
    &:focus-within {
      outline: 2px solid #324dc7;
      outline-offset: 4px;
      border-radius: 2px;
    }
  }

  .cb-dropdown.keyboard-selector {
    margin-bottom: 12px;
  }

  .cb-dropdown-toggle {
    justify-content: space-between;
    align-items: center;
    width: 100%;
    height: auto;
    padding-left: 0;
    padding-right: 0;
    text-align: left;
  }

  .zoom {
    .cb-dropdown-menu {
      position: absolute;
      width: auto;
      top: 0;
      left: 0;
    }
  }

  .cb-dropdown-menu {
    max-height: 144px;
    min-width: auto;
    overflow-y: auto;
    position: fixed;
    width: calc(198px - var(--widthOffset)) !important;
    top: auto;
    left: auto;

