6604:
.conversation-item {
  display: flex;
  flex-direction: row;
  overflow: hidden;
  margin: 0px;

  &.left {
    justify-content: flex-start;
  }

  &.right {
    justify-content: flex-end;
  }

  .audio-player,
  .audio-recorder {
    min-width: 350px;
    width: 70%;
    min-height: 128px;
  }

  // These blocks change the coloring of the playback controls based on the active/inactive flag
  &:active {
    .audio-player,
    .audio-recorder {
      color: white;
    }

    .player-box {
      background: #15327f;
    }
  }

  &.inactive {
    .audio-player,
    .audio-recorder {
      color: #888;
    }

    .player-box {
      background: #d9d9d9;
      color: #888888;

      .captions {
        background: #d9d9d9;
      }
    }

    .time-remaining {
      font-size: 14px;
      line-height: 16px;
      font-weight: 400;
      color: #888888;
    }
  }

  .conversation-indicator {
    width: 12px;
    height: 32px;
    padding: 0px;
    flex-grow: 0;
    align-self: flex-start;
  }

  .conversation-pointer {
    width: 28px;
    height: 32px;
    border-right: 12px solid transparent;
    border-bottom: 0px solid transparent;
    border-left: 12px solid transparent;

    &.active {
      border-top: 24px solid #15327f;
    }

    &.inactive {
      border-top: 24px solid #d9d9d9;
    }

    &.right {
      transform: translateX(-16px);
    }
  }

  .audio-player {
    margin-top: 0px;
    margin-bottom: 0px;
  }
}

