/**
  * This is a hack for adding visual focus to Apricot's Tab component; the
  * user can navigate between tabs using the arrow keys, but no visual feedback
  * is provided. This adds a visual outline when a tab is focused.
*/
.visual-focus-hack {
  border: 2px solid transparent;
  margin: -2px;

  &:focus {
    border: 2px solid #00f;
    outline: none;
    border-radius: 4px;
  }
}

img {
  /* stylelint-disable-next-line property-no-unknown */
  user-drag: none;
  -webkit-user-drag: none;
