7485:
#reference-sheets-container {
  position: relative;
  @at-root body &:has(#exam-reference-sheet:visible) {
    @at-root body div.CtxtMenu_MenuFrame {
      z-index: 901 !important;
    }
  }
}
#reference-sheet {
  container-type: inline-size;
  container-name: reference-sheet;

  &.ref-v2 {
    &.ap-chemistry {
      @import 'ap-chemistry';
    }
    &.ap-statistics {
      @import 'ap-statistics';
    }
    &.ap-cs-a {
      @import 'ap-cs-a';
    }
    &.ap-cs-principles {
      @import 'ap-cs-principles';
    }
    &.ap-latin {
      @import 'ap-latin';
    }

    // Pseudocode boxes (used by CSP) — force Courier Prime on the box so all
    // descendants inherit consistently, regardless of whether the source HTML
    // wraps content in a `<code>` element or relies on td font-family.
    .procedure-box,
    .statement-box {
      font-family: "Courier Prime";
      font-size: 14px;
      line-height: 1em;
    }

    .cb-font-weight-bold {
      font-size: 15px;
    }
    .cb-accordion .cb-accordion-panels .cb-accordion-container .cb-accordion-panel.cb-in {
      overflow: hidden;
    }

    // Default .cb-table cell alignment. cb-align-{left,center,right} on
    // the table and inline styles still win on specificity.
    .cb-table > thead > tr > th,
    .cb-table > tbody > tr > th,
    .cb-table > tfoot > tr > th {
      text-align: center;
      vertical-align: middle;
    }
    // <th> inside tbody/tfoot is conventionally a row-header: left-align.
    // Don't require scope="row" — source AP HTML is inconsistent about it.
    .cb-table > tbody > tr > th,
    .cb-table > tfoot > tr > th {
      text-align: left;
    }
    .cb-table > thead > tr > td,
    .cb-table > tbody > tr > td,
    .cb-table > tfoot > tr > td {
      text-align: left;
      vertical-align: middle;
    }

    // Apricot cb-align-{left,center,right} utility classes — source AP HTML
    // applies these on <table> (e.g. table-a/b/c use cb-align-right). Apricot
    // CSS isn't loaded by the hybrid renderer, so reproduce them here.
    .cb-table.cb-align-left > * > tr > td,
    .cb-table.cb-align-left > * > tr > th {
      text-align: left;
    }
    .cb-table.cb-align-center > * > tr > td,
    .cb-table.cb-align-center > * > tr > th {
      text-align: center;
    }
    .cb-table.cb-align-right > * > tr > td,
    .cb-table.cb-align-right > * > tr > th {
      text-align: right;
    }

    // RS grid system (JSON-rendered ref sheets)
    // rs-panel = row, rs-group = column, rs-item = content block
    .rs-panel {
      background-color: #f5f6fc;
      overflow-x: auto;
      overflow-y: hidden;
      padding: 8px;
      .rs-group {
        background-color: #fff;
        border-radius: 8px;
        padding: 8px;
        display: flex;
        flex-wrap: wrap;
        // Single rs-item in group gets full width
        > .rs-item:only-of-type {
          width: 100%;
        }
        .rs-item,
        .rs-panel-header,
        .rs-panel-footer {
          border-radius: 8px;
          padding: 5px 8px;
          box-sizing: border-box;
          min-width: 0;
          font-family: "Noto Serif", serif;
          font-size: 15px;
          line-height: 23px;
          .rs-item-content {
            overflow-x: auto;
            overflow-y: hidden;
            max-width: 100%;
            min-width: 0;
            box-sizing: border-box;
            padding: 5px 4px;
            .ap-custom-scroll {
              width: 99%;
              overflow-x: auto;
              overflow-y: hidden;
            }
          }
          h3,
          li {
            font-family: "Noto Serif", serif;
            font-size: 15px;
            line-height: 23px;
          }
        }
        .rs-item {
          h3 {
            margin-bottom: 4px;
          }
          // Title is rendered outside rs-item-content so it never scrolls
          // with overflowing content (e.g. wide MathML expressions).
          > .rs-item-title {
            font-weight: bold;
            font-size: 15px;
            line-height: 23px;
            color: #1e1e1e;
          }
        }
        .rs-panel-header,
        .rs-panel-footer {
          width: 100%;
          font-family: "Noto Serif", serif;
          font-size: 15px;
          font-weight: bold;
          font-stretch: normal;
          font-style: normal;
          line-height: 1.53;
          letter-spacing: -0.1px;
          text-align: left;
          color: #1e1e1e;
          .rs-item-content {
            padding-top: 0;
            padding-bottom: 0;
          }
        }
        .rs-panel-footer {
          margin-top: 4px;
          margin-bottom: 8px;
          font-weight: normal;
        }
      }
      &.rs-type-table {
        .rs-group {
          .rs-panel-header {
            padding-bottom: 0;
          }
        }
      }
      &.rs-type-definition {
        .rs-group {
          .rs-panel-header,
          .rs-panel-footer,
          .rs-item {
            padding-top: 0;
            padding-bottom: 0;
              .rs-item-content .MathJax * {
                color: #1e1e1e !important;
              }
          }
        }
      }
    }

    // Keep MathML / MathJax equations on a single line so they extend the
    // .rs-item-content horizontal scroll region instead of breaking mid-formula.
    .rs-panel .rs-item-content {
      math,
      mjx-container,
      mjx-container * {
        white-space: nowrap !important;
      }

      // Source HTML wraps math in <div class="overflow-x-scroll">, which makes
      // browsers auto-promote overflow-y to auto and show a spurious vertical
      // scrollbar. Parent .rs-item-content already scrolls horizontally.
      .overflow-x-scroll {
        overflow: visible;
      }
    }

    @container reference-sheet (max-width: 574px) {
      .rs-panel .rs-group .rs-item {
        width: calc(50% - 4px);
      }
    }

    @container reference-sheet (min-width: 575px) {
      .rs-panel .rs-group .rs-item {
        width: calc(25% - 6px);
      }
    }

    // Panel-level full-width override: all items span 100%
    .rs-panel.rs-default-width-full .rs-group .rs-item {
      width: 100%;
    }

    // note: we will need to make this more specific for specific panels
    .rs-panel.rs-default-width-full .rs-group .rs-item .row {
      margin-left: 0;
      margin-right: 0;
      display: grid;
      grid-template-columns: 53px 15px 20px auto;
      grid-template-rows: auto auto;
      .col-xs-1 {
        padding-left: 0;
        padding-right: 0;
      }
    }

    .cb-accordion {
      .cb-accordion-panels .cb-accordion-container {
        background-color: #f5f6fc;
        .cb-accordion-heading {
          background-color: #e6edf8;
          padding: 8px 24px;
          border-color: #fff;
          .cb-accordion-heading-title {
            span {
              color: #28369a;
              font-family: Roboto;
              font-weight: 700;
            }
          }
        }
      }
    }

    // Tabs
    .cb-tabs-menu,
    .cb-tabs-container {
      max-width: 100%;
      box-sizing: border-box;
      margin-top: 0;
    }

    .cb-tabs-menu {
      display: flex;
      flex-wrap: nowrap;
      overflow-x: auto;
      overflow-y: hidden;
      width: 100%;
      max-width: 100%;
      box-sizing: border-box;
      -webkit-overflow-scrolling: touch;
      background-color: #F5F7FC;
      margin: 0 0 0 0;
      height: 48px;
      ul {
        display: flex;
        width: 100%;
        margin: 0;
        padding: 0;
        list-style: none;
        li {
          flex: 1;
          display: flex;
          justify-content: center;
          align-items: center;
        }
      }
    }

    .cb-tabs-menu .cb-menu-link {
      white-space: nowrap;
      font-family: Roboto;
      font-size: 14px; 
      font-weight: bold;
      font-stretch: normal;
      font-style: normal;
      line-height: 1.14;
      letter-spacing: normal;
      justify-content: center;
      width: 100%;
      border-bottom: 2px solid #d9d9d9;
      svg {
        fill: currentColor;
        * {
          fill: currentColor;
        }
      }
      &.cb-selected {
        background-color: #283599;
        color: #fff;
      }
    }

    // Spacing utilities
    .cb-padding-top-24 {
      padding-top: 24px;
    }
    .cb-padding-left-24 {
      padding-left: 24px;
    }
    .cb-padding-right-24 {
      padding-right: 24px;
    }
    .cb-padding-bottom-24 {
      padding-bottom: 24px;
    }
    .cb-padding-24 {
      padding: 24px;
    }
    .cb-padding-top-4 {
      padding-top: 4px;
    }
    .cb-margin-bottom-4 {
      margin-bottom: 4px;
    }

    // Math content
    .math-equation {
      margin: 0;
      font-size: 1.05rem;
      line-height: 2;
    }

    .math-definition {
      margin: 0 0 2px;
      color: #1e1e1e;
    }

    .MathJax:not(th *) {
      color: #28369a;
    }

    th,
    td {
      font-family: "Noto Serif", serif;
      font-size: 15px;
      line-height: 23px;
    }

    .cb-table thead,
    .cb-table th[scope="col"],
    .cb-table th[scope="colgroup"] {
      background-color: #f0f0f0;
      font-weight: bold;
      color: #1f1f1f;
    }
    .cb-table th,
    .cb-table td {
      border: 1px solid #888888;
    }
    .cb-table {
      border-collapse: collapse;
    }

    .cb-accordion .cb-accordion-controls {
      height: 40px;
      display: flex;
      justify-content: center;
      align-items: center;
      padding-right: 16px;
      margin-bottom: 0;
    }

    .cb-accordion
      .cb-accordion-panels
      .cb-accordion-container
      .cb-accordion-panel
      .cb-accordion-panel-content {
      background-color: #f5f6fc !important;
    }

    .rs-section-heading {
      font-size: 1.125rem;
      font-weight: 700;
      color: #1e1e1e;
      padding: 16px 24px 8px;
      margin: 0;
    }
    .rs-section-content {
      padding: 16px 24px;
      color: #505050;
    }
  }
}
