.line-reader-content-container {
  background-color: transparent;

  .click-blocker-top,
  .click-blocker-left,
  .click-blocker-right,
  .click-blocker-bottom {
    position: absolute;
    pointer-events: auto;
    background-color: transparent;
  }

  .click-blocker-top {
    top: 44px;
    left: 0;
    height: 46px;
    width: 100%;
  }
  .click-blocker-left {
    top: 90px;
    left: 0;
    height: 80px;
    width: 16px;
  }
  .click-blocker-right {
    top: 90px;
    left: calc(100% - 16px);
    height: 80px;
    width: 16px;
  }
  .click-blocker-bottom {
    top: 114px;
    left: 0;
    height: 88px;
    width: 100%;

    &.viewport-size-2 {
      top: 138px;
      height: 64px;
    }

    &.viewport-size-3 {
      top: 162px;
      height: 40px;
    }
  }

  .viewport-expand-collapse-button {
    position: absolute;
    left: calc(50% - 12px);
    bottom: 10px;
    height: 24px;
    width: 24px;
    border-radius: 6px;
    cursor: pointer;
    background-color: transparent;
    pointer-events: auto;
    z-index: 1;
    border-style: none;
    padding: 0 0 0 5px;

    &:hover {
      background-color: #f0f0f0;
    }

    &:focus {
      outline-color: #f0f0f0;
      outline-style: solid;
      outline-width: 2px;
      outline-offset: 2px;
    }

    &.reversed-triangle {
      padding-bottom: 3px;
    }

    .viewport-expand-collapse-triangle {
      width: 0px;
      height: 0px;
      background-color: transparent;
      border-top: 7px solid #b2b2b2;
      border-left: 7px solid transparent;
      border-right: 7px solid transparent;
      border-bottom: unset;
      will-change: transform;
      transition: all 0.5s;

      &.reversed-triangle {
        transform: rotate(180deg);
      }
    }
  }

  @media (forced-colors: active) {
    .viewport-expand-collapse-button {
      forced-color-adjust: none !important;
      background-color: #ffffff !important;
      border: 1px solid #1e1e1e;
      &:focus {
        background-color: #1e1e1e !important;
        border: 1px solid #1e1e1e;
      }

      &:hover {
        background-color: #1e1e1e !important;
        border: 1px solid #1e1e1e;
      }
    }
  }

  .line-reader-viewport {
    height: 160px;
    border: 16px solid rgba(30, 30, 30, 0.9);
    border-top-width: 48px;
    border-bottom-width: 88px;
    background-color: rgba(30, 30, 30, 0.1);

    &.viewport-size-2 {
      border-bottom-width: 64px;
    }

    &.viewport-size-3 {
      border-bottom-width: 40px;
    }
  }

  .line-reader-instructions {
    position: absolute;
    top: 49px;
    width: 100%;
    text-align: center;
    color: #f7f7f7;
    font-size: 13px;
    font-family: "Roboto";
    padding-right: 16px;
    padding-left: 16px;
    line-height: 16px;

    img {
      padding-bottom: 2px;
      padding-right: 6px;
    }
  }
}

