@import "./variables";

.mcr-option-container {
  display: block;
  position: relative;
  cursor: pointer;
  font-size: 16px;
  color: $fontColorAlt;

  input {
    position: absolute;
    opacity: 0;
    cursor: pointer;

    // opacity 0 makes the actual input element invisible, but we still need it the proper size and z-index for mac text to speech functionality
    height: 20px;
    width: 20px;
    z-index: 1;
    top: 3px;
    left: 1px;

    &:checked {
      ~ .mcr-custom-option {
        background-color: $fontColorAlt2;
