    font-family: Roboto;
    font-weight: bold;
    width: 20px;
    height: 20px;
    margin: 2px 0px 0px 1px;
    padding: 0;
    border-radius: 2px;

    .check-mark {
      visibility: hidden;
      padding-top: 1px;
    }
  }

  .eliminated-option {
