8898:
@import "./utility/variables";

.esat-styled-window {
  border: solid 1px #505050;
  color: $fontColor;
}

img {
  /* stylelint-disable-next-line property-no-unknown */
  user-drag: none;
  -webkit-user-drag: none;
  -moz-user-drag: none;
  -o-user-drag: none;
}

:root {
  overflow: hidden;
}
// scrollbars on mac isnt grabbable: the following -webkit-scrollbar stuff fixes this
// example: https://stackoverflow.com/questions/7492062/css-overflow-scroll-always-show-vertical-scroll-bar

$scrollbar-width: 16px;
::-webkit-scrollbar {
  /* stylelint-disable-next-line property-no-vendor-prefix */
  -webkit-appearance: none;
  background-color: transparent;

  &:vertical {
    width: $scrollbar-width;
  }
  &:horizontal {
    height: $scrollbar-width;
  }
}

::-webkit-scrollbar-track-piece {
  background-color: transparent;
}

::-webkit-scrollbar-track {
  background-color: transparent;

  &:hover {
    background-color: rgba(244, 244, 244, 0.9);
    &:horizontal {
      border-top: 1px solid #d8d8d8;
    }

    &:vertical {
      border-left: 1px solid #d8d8d8;
    }
  }
}

::-webkit-scrollbar-corner {
  background-color: transparent;
}

::-webkit-scrollbar-thumb {
  border-radius: $scrollbar-width;
  background-color: rgba(black, 0.5);
  border: 4.5px solid transparent;
  background-clip: content-box;
  &:hover {
    border: 2.5px solid transparent;
  }
}

::-webkit-scrollbar-button {
  display: none;
}

::selection {
  background: #c6d4ea;
}

button {
  color: $fontColor;

  &[disabled] {
    color: $fontColorDisabled;
  }
}

// CJ lang specific font/spacing overrides
*:lang(ja) {
  font-family: "Noto Serif JP" !important;
  font-size: 16px !important;
  line-height: 26px !important;
  letter-spacing: normal !important;

  .dap_numbered_paragraph_group {
    & > p:first-child > span.paragraph_number {
      margin-top: -27px;
    }
  }
}

*:lang(zh) {
  font-family: "Noto Serif SC" !important;
  font-size: 16px !important;
  line-height: 26px !important;
  letter-spacing: 0.6px !important;

  .dap_numbered_paragraph_group {
    & > p:first-child > span.paragraph_number {
      margin-top: -27px;
    }
  }
}

*:is(h1, h2, h3, h4, h5, h6):lang(ja),
*:is(h1, h2, h3, h4, h5, h6):lang(zh) {
  font-weight: bold !important;
}

.cb-exam-header-container {
  .cb-exam-header {
    // menu requires override of line height to stay correct in the header.
    *:lang(ja),
    *:lang(zh) {
      line-height: 21px !important;
    }
  }
}

.cb-esat-exam {
  height: 100vh;
  color: $fontColor;
}

.height-full {
  min-height: 100%;
}

.unstyled-button {
  background: transparent;
  border: 0;
  outline-offset: 4px;

  // apricot glyph weirdness correction attempt
  z-index: 0;
  span {
    z-index: inherit;
  }
}

.footnotes-divider {
  margin: 16px 0px 16px 0px;
  border-color: #979797;
  border-style: solid;
}

.cb-discrete-question-subcontainer {
  div[contenteditable="true"] {
    max-width: 664px;
  }
}

// split-question's styles exist here to prevent themi from being overridden by global styles above due to the
// way the components are nested.
.split-question-container {
  .gutter.gutter-horizontal {
    cursor: col-resize;
    margin: 0;
    background-color: #ccc;
  }

  .split-pane {
    overflow: auto;
    .cb-discrete-question-subcontainer {
      width: 100%;
      max-width: 664px;
      outline: none;
    }
  }

  .split-pane-content-left {
    padding-right: 4px;
    padding-bottom: 12px;
    min-width: 240px;
    max-width: 664px;
    margin: auto;
    position: relative;

    .stimulus-scroll-spacer {
      height: 380px;
    }
  }

  .split-pane-content-right {
    min-height: 100%;
    padding-top: 36px;
    padding-bottom: 12px;
    min-width: min-content;
    max-width: 664px;
    margin: auto;

    &.frq {
      min-width: 215px;
    }

    .cb-exam-question-container {
      .cb-discrete-question {
        .cb-discrete-question-subcontainer {
          padding-right: 6px;
        }
      }
    }

    .ck-editor {
      .ck-editor__main {
        ::selection {
          background: rgba(0, 0, 0, 0.2);
          color: inherit;
        }
      }
    }
  }

  // note that this does not scale with zoom due to the way we are zooming and may need to be addressed
  @media screen and (min-width: 1920px) {
    .split-pane-content-left {
      margin-right: 107px;
    }
    .split-pane-content-right {
      margin-left: 107px;
    }
  }

  @media screen and (min-height: 1080px) {
    .split-pane-content-left {
      .stimulus-scroll-spacer {
        height: 700px;
      }
    }
  }

  @media screen and (min-height: 1440px) {
    .split-pane-content-left {
      .stimulus-scroll-spacer {
        height: 1000px;
      }
    }
  }

  .primereact-splitter {
    position: absolute;
    display: flex;
    flex-direction: row;
    width: 100%;
    height: 100%;
    overflow: hidden;

    .p-splitter-gutter {
      background-color: #888888;
      z-index: 2;
      position: relative;

      &::before {
        content: "";
        position: absolute;
        top: calc(20% - 12px);
        width: 48px;
        height: 48px;
        z-index: 1;
        cursor: grab;
      }

      &:active::before {
        cursor: grabbing;
      }

      .p-splitter-gutter-handle {
        /* scales handle outside of container hence units are pre-scale sizes */
        position: absolute;
        width: 14px;
        height: 28px;
        background-repeat: no-repeat;
        background-position: center center;
        border: 1px white solid;
        border-radius: 2px;
        box-sizing: border-box;
        top: calc(20%);
        z-index: 2;
        outline-offset: 2px;
        &:hover {
          cursor: grab;
        }
        &:active {
          cursor: grabbing;
        }
        &:hover,
        &:active {
          filter: brightness(2.8);
        }
      }
    }

    .split-pane {
      position: relative;
      & > .cb-exam-question-container {
        width: 100%;
      }
    }
    .cb-set-pane-container-left-outer {
      overflow: hidden !important;
      display: flex;
      flex-direction: row;
      height: 100%;

      section {
        outline-offset: -4px;
        overflow-x: auto;
        width: 100%;
        scrollbar-gutter: stable;
      }

      .cb-set-pane-container-left {
        margin: 32px 0 4px 2px;
      }
    }

    .cb-set-pane-container-right {
      overflow: hidden !important;
      margin: 0px;
      padding-top: 0px;

      section {
        outline-offset: -4px;
        height: 100%;
        overflow-x: auto;
        scrollbar-gutter: stable;
      }
    }
  }

  .split-pane-content-container {
    padding: 0px 38px;
  }
}

.p-splitter-resizing .p-splitter-panel {
  user-select: none !important;
  /* stylelint-disable-next-line property-no-vendor-prefix */
  -webkit-user-select: none !important;
}

.dcg-grapher.dcg-grapher-2d {
  visibility: inherit !important;
}

.dcg-download-button {
  visibility: hidden;
  display: none !important;
}

