9371:
.accent-picker {
  position: relative;
}

.accent-picker-wrapper {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 9998;
  pointer-events: none;
}

.accent-picker-popup {
  position: absolute;
  z-index: 9999;
}

.accent-picker-fixed {
  position: fixed;
  z-index: 9999;
}

/* Position relative to cursor/character, similar to native accent popup */

/* Ensure visibility */
.accent-picker-popup {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.accent-picker-popup {
  display: flex;
  flex-wrap: nowrap;
  justify-content: center;
  align-items: center;
  gap: 2px; /* Reduced from 4px to match macOS tighter spacing */
  padding: 4px 6px; /* Reduced from 8px 12px for a more compact look */
  background: rgba(0, 0, 0, 0.75); /* Darker background like macOS */
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px; /* Slightly reduced from 8px */
  box-shadow: 0 5px 12px rgba(0, 0, 0, 0.3); /* Subtler shadow */
  -webkit-backdrop-filter: blur(10px);
  backdrop-filter: blur(10px);
  min-height: 36px; /* Reduced from 44px */
  /* animation: popIn 0.12s cubic-bezier(0.2, 0, 0.13, 1); Faster, snappier animation */
  /* transform-origin: bottom center; */
}

/* Add a subtle animation for popup appearance */
@keyframes popIn {
  0% {
    transform: scale(0.95) translateY(4px); /* Subtler initial scale */
    opacity: 0;
  }
  100% {
    transform: scale(1) translateY(0);
    opacity: 1;
  }
}

/* Remove debug styling - no longer needed */

.accent-picker-item {
  padding: 4px 6px; /* Reduced padding */
  cursor: default; /* Changed from pointer to match native feel */
  margin: 0;
  font-size: 16px; /* Slightly smaller font */
  border-radius: 4px; /* Reduced from 6px */
  background: transparent;
  border: none;
  transition: background-color 0.08s ease; /* Faster transition */
  display: flex;
  justify-content: center;
  align-items: center;
  min-width: 24px; /* Reduced from 32px */
  min-height: 28px; /* Reduced from 32px */
  color: white; /* Changed from black to white */
  text-align: center;
  font-weight: 400;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
}

.accent-picker-item:hover {
  background: rgba(255, 255, 255, 0.15); /* Subtler hover effect */
}

.accent-picker-item:active {
  background: rgba(255, 255, 255, 0.2); /* Subtler active effect */
}

.accent-picker-popup ul {
  list-style-type: none;
  padding: 0;
  margin: 0;
}

.accent-picker-popup ul li {
  padding: 4px 8px;
  cursor: pointer;
}

/* Remove title styling - not using title in native-style popup */

